     8→import types_extended
     9→
    10→// ============================================================================
    11→// 1. ARRAY TYPE & CONSTRUCTORS
    12→// ============================================================================
    13→
    14→// Array wrapper with metadata
    15→record Array[T] {
    16→  data: [T],
    17→  shape: [Int],  // dimensions
    18→  size: Int      // total elements
    19→}
    20→
    21→// Create empty array
    22→function new_array[T](size: Int) -> Array[T] = {
    23→  Array {
    24→    data: [],
    25→    shape: [size],
    26→    size: 0
    27→  }
    28→}
    29→
    30→// Create array with initial values
    31→function array[T](items: [T]) -> Array[T] = {
    32→  Array {
    33→    data: items,
    34→    shape: [len(items)],
    35→    size: len(items)
    36→  }
    37→}
    38→
    39→// Create array of zeros
    40→function zeros[T](size: Int) -> Array[Int] = {
    41→  let arr = Array {
    42→    data: [],
    43→    shape: [size],
    44→    size: 0
    45→  }
    46→  fold_range(0, size, arr, fn(a, _) -> {
    47→    a.data = append(a.data, 0)
    48→    a.size = a.size + 1
    49→    a
    50→  })
    51→}
    52→
    53→// Create array of ones
    54→function ones[T](size: Int) -> Array[Int] = {
    55→  let arr = Array {
    56→    data: [],
    57→    shape: [size],
    58→    size: 0
    59→  }
    60→  fold_range(0, size, arr, fn(a, _) -> {
    61→    a.data = append(a.data, 1)
    62→    a.size = a.size + 1
    63→    a
    64→  })
    65→}
    66→
    67→// Create range array
    68→function range_array(start: Int, end: Int) -> Array[Int] = {
    69→  let result = []
    70→  let arr = fold_range(start, end, Array {
    71→    data: result,
    72→    shape: [end - start],
    73→    size: 0
    74→  }, fn(a, i) -> {
    75→    a.data = append(a.data, i)
    76→    a.size = a.size + 1
    77→    a
    78→  })
    79→  arr
    80→}
    81→
    82→// ============================================================================
    83→// 2. ARRAY INDEXING & ACCESS
    84→// ============================================================================
    85→
    86→// Get element at index
    87→function get[T](arr: Array[T], index: Int) -> Option[T] = {
    88→  if index >= 0 && index < arr.size {
    89→    Some(arr.data[index])
    90→  } else {
    91→    None
    92→  }
    93→}
    94→
    95→// Set element at index (returns new array)
    96→function set[T](arr: Array[T], index: Int, value: T) -> Array[T] = {
    97→  if index >= 0 && index < arr.size {
    98→    let new_data = arr.data
    99→    new_data[index] = value
   100→    Array {
   101→      data: new_data,
   102→      shape: arr.shape,
   103→      size: arr.size
   104→    }
   105→  } else {
   106→    arr
   107→  }
   108→}
   109→
   110→// Get element safely with bounds checking
   111→function at[T](arr: Array[T], index: Int) -> Result[T, String] = {
   112→  if index >= 0 && index < arr.size {
   113→    Ok(arr.data[index])
   114→  } else {
   115→    Err(format("Index out of bounds: {}", index))
   116→  }
   117→}
   118→
   119→// Get first element
   120→function first[T](arr: Array[T]) -> Option[T] = {
   121→  if arr.size > 0 {
   122→    Some(arr.data[0])
   123→  } else {
   124→    None
   125→  }
   126→}
   127→
   128→// Get last element
   129→function last[T](arr: Array[T]) -> Option[T] = {
   130→  if arr.size > 0 {
   131→    Some(arr.data[arr.size - 1])
   132→  } else {
   133→    None
   134→  }
   135→}
   136→
   137→// ============================================================================
   138→// 3. ARRAY OPERATIONS
   139→// ============================================================================
   140→
   141→// Get array length
   142→function len[T](arr: Array[T]) -> Int = arr.size
   143→
   144→// Check if empty
   145→function is_empty[T](arr: Array[T]) -> Bool = arr.size == 0
   146→
   147→// Reverse array
   148→function reverse[T](arr: Array[T]) -> Array[T] = {
   149→  let reversed = fold(arr.data, [], fn(acc, item) -> {
   150→    [item] + acc
   151→  })
   152→  Array {
   153→    data: reversed,
   154→    shape: arr.shape,
   155→    size: arr.size
   156→  }
   157→}
   158→
   159→// Append element
   160→function push[T](arr: mutable Array[T], item: T) -> Unit = {
   161→  arr.data = append(arr.data, item)
   162→  arr.size = arr.size + 1
   163→  arr.shape[0] = arr.size
   164→}
   165→
   166→// Remove last element
   167→function pop[T](arr: mutable Array[T]) -> Option[T] = {
   168→  if arr.size > 0 {
   169→    let item = arr.data[arr.size - 1]
   170→    arr.size = arr.size - 1
   171→    arr.shape[0] = arr.size
   172→    Some(item)
   173→  } else {
   174→    None
   175→  }
   176→}
   177→
   178→// Concatenate arrays
   179→function concat[T](a: Array[T], b: Array[T]) -> Array[T] = {
   180→  Array {
   181→    data: a.data + b.data,
   182→    shape: [a.size + b.size],
   183→    size: a.size + b.size
   184→  }
   185→}
   186→
   187→// Slice array [start:end)
   188→function slice[T](arr: Array[T], start: Int, end: Int) -> Array[T] = {
   189→  let sliced = fold_range(start, min(end, arr.size), [], fn(acc, i) -> {
   190→    if i >= 0 && i < arr.size {
   191→      append(acc, arr.data[i])
   192→    } else {
   193→      acc
   194→    }
   195→  })
   196→  Array {
   197→    data: sliced,
   198→    shape: [len(sliced)],
   199→    size: len(sliced)
   200→  }
   201→}
   202→
   203→// ============================================================================
   204→// 4. ARRAY TRANSFORMATIONS
   205→// ============================================================================
   206→
   207→// Map function over array
   208→function map[T, U](arr: Array[T], f: fn(T) -> U) -> Array[U] = {
   209→  let mapped = fold(arr.data, [], fn(acc, item) -> {
   210→    append(acc, f(item))
   211→  })
   212→  Array {
   213→    data: mapped,
   214→    shape: [len(mapped)],
   215→    size: len(mapped)
   216→  }
   217→}
   218→
   219→// Filter array
   220→function filter[T](arr: Array[T], predicate: fn(T) -> Bool) -> Array[T] = {
   221→  let filtered = fold(arr.data, [], fn(acc, item) -> {
   222→    if predicate(item) {
   223→      append(acc, item)
   224→    } else {
   225→      acc
   226→    }
   227→  })
   228→  Array {
   229→    data: filtered,
   230→    shape: [len(filtered)],
   231→    size: len(filtered)
   232→  }
   233→}
   234→
   235→// Fold over array
   236→function fold[T, U](arr: Array[T], init: U, f: fn(U, T) -> U) -> U = {
   237→  fold_impl(arr.data, init, f)
   238→}
   239→
   240→// Reduce array to single value
   241→function reduce[T](arr: Array[T], f: fn(T, T) -> T) -> Option[T] = {
   242→  if arr.size == 0 {
   243→    None
   244→  } else {
   245→    let init = arr.data[0]
   246→    let result = fold_impl(tail(arr.data), init, f)
   247→    Some(result)
   248→  }
   249→}
   250→
   251→// ============================================================================
   252→// 5. ARRAY COMPREHENSIONS
   253→// ============================================================================
   254→
   255→// Array comprehension: [f(x) for x in arr]
   256→function array_comp[T, U](arr: Array[T], f: fn(T) -> U) -> Array[U] = {
   257→  map(arr, f)
   258→}
   259→
   260→// Conditional comprehension: [f(x) for x in arr if p(x)]
   261→function array_comp_cond[T, U](arr: Array[T], f: fn(T) -> U, predicate: fn(T) -> Bool) -> Array[U] = {
   262→  let filtered = filter(arr, predicate)
   263→  map(filtered, f)
   264→}
   265→
   266→// Range comprehension: [f(i) for i in range(start, end)]
   267→function range_comp(start: Int, end: Int, f: fn(Int) -> Int) -> Array[Int] = {
   268→  let range_arr = range_array(start, end)
   269→  map_int(range_arr, f)
   270→}
   271→
   272→// ============================================================================
   273→// 6. ARRAY PROPERTIES & AGGREGATIONS
   274→// ============================================================================
   275→
   276→// Sum array elements
   277→function sum(arr: Array[Int]) -> Int = {
   278→  fold_impl(arr.data, 0, fn(acc, x) -> acc + x)
   279→}
   280→
   281→// Product of array elements
   282→function product(arr: Array[Int]) -> Int = {
   283→  fold_impl(arr.data, 1, fn(acc, x) -> acc * x)
   284→}
   285→
   286→// Min element
   287→function min_elem(arr: Array[Int]) -> Option[Int] = {
   288→  if arr.size == 0 {
   289→    None
   290→  } else {
   291→    Some(fold_impl(arr.data, arr.data[0], fn(acc, x) -> {
   292→      if x < acc { x } else { acc }
   293→    }))
   294→  }
   295→}
   296→
   297→// Max element
   298→function max_elem(arr: Array[Int]) -> Option[Int] = {
   299→  if arr.size == 0 {
   300→    None
   301→  } else {
   302→    Some(fold_impl(arr.data, arr.data[0], fn(acc, x) -> {
   303→      if x > acc { x } else { acc }
   304→    }))
   305→  }
   306→}
   307→
   308→// Average
   309→function mean(arr: Array[Int]) -> Option[Float] = {
   310→  if arr.size == 0 {
   311→    None
   312→  } else {
   313→    Some(as_float(sum(arr)) / as_float(arr.size))
   314→  }
   315→}
   316→
   317→// ============================================================================
   318→// 7. HELPER FUNCTIONS
   319→// ============================================================================
   320→
   321→function fold_impl[T, U](items: [T], init: U, f: fn(U, T) -> U) -> U = {
   322→  fold_items(items, init, f, 0, len(items))
   323→}
   324→
   325→function fold_items[T, U](items: [T], acc: U, f: fn(U, T) -> U, index: Int, limit: Int) -> U = {
   326→  if index >= limit {
   327→    acc
   328→  } else {
   329→    fold_items(items, f(acc, items[index]), f, index + 1, limit)
   330→  }
   331→}
   332→
   333→function fold_range(start: Int, end: Int, initial: Any, f: fn(Any, Int) -> Any) -> Any = {
   334→  if start >= end {
   335→    initial
   336→  } else {
   337→    fold_range(start + 1, end, f(initial, start), f)
   338→  }
   339→}
   340→
   341→function map_int(arr: Array[Int], f: fn(Int) -> Int) -> Array[Int] = {
   342→  map(arr, f)
   343→}
   344→
   345→function tail[T](items: [T]) -> [T] = {
   346→  if len(items) <= 1 {
   347→    []
   348→  } else {
   349→    slice_list(items, 1, len(items))
   350→  }
   351→}
   352→
   353→function slice_list[T](items: [T], start: Int, end: Int) -> [T] = {
   354→  fold_range(start, min(end, len(items)), [], fn(acc, i) -> {
   355→    if i >= start && i < end {
   356→      append(acc, items[i])
   357→    } else {
   358→      acc
   359→    }
   360→  })
   361→}
   362→
   363→function min(a: Int, b: Int) -> Int = {
   364→  if a < b { a } else { b }
   365→}
   366→
   367→function append[T](arr: [T], item: T) -> [T] = {
   368→  arr + [item]
   369→}
   370→
   371→function as_float(x: Int) -> Float = {
   372→  // Type conversion - simplified
   373→  x as Float
   374→}
