   321→function sqrt_newton(x: Float, guess: Float, epsilon: Float, iter: Int) -> Float = {
   322→  if iter == 0 || abs_float(guess * guess - x) < epsilon {
   323→    guess
   324→  } else {
   325→    let next_guess = (guess + x / guess) / 2.0
   326→    sqrt_newton(x, next_guess, epsilon, iter - 1)
   327→  }
   328→}
   329→
   330→function cbrt_newton(x: Float, guess: Float, epsilon: Float, iter: Int) -> Float = {
   331→  if iter == 0 || abs_float(guess * guess * guess - x) < epsilon {
   332→    guess
   333→  } else {
   334→    let next_guess = (2.0 * guess + x / (guess * guess)) / 3.0
   335→    cbrt_newton(x, next_guess, epsilon, iter - 1)
   336→  }
   337→}
   338→
   339→function exp_taylor(x: Float, term: Float, sum: Float, n: Int, limit: Int) -> Float = {
   340→  if n >= limit || abs_float(term) < 0.000001 {
   341→    sum
   342→  } else {
   343→    let next_term = term * x / as_float(n)
   344→    exp_taylor(x, next_term, sum + next_term, n + 1, limit)
   345→  }
   346→}
   347→
   348→function log_approx(x: Float) -> Float = {
   349→  // Simplified approximation
   350→  0.0
   351→}
   352→
   353→function sin_taylor(x: Float, term: Float, factorial: Float, n: Int, limit: Int) -> Float = {
   354→  if n >= limit || abs_float(term) < 0.000001 {
   355→    term
   356→  } else {
   357→    let n_float = as_float(2 * n + 1)
   358→    let next_term = -term * x * x / (n_float * (n_float - 1.0))
   359→    term + sin_taylor(x, next_term, factorial, n + 1, limit)
   360→  }
   361→}
   362→
   363→function cos_taylor(sum: Float, term: Float, n: Int, limit: Int, x: Float) -> Float = {
   364→  if n >= limit || abs_float(term) < 0.000001 {
   365→    sum
   366→  } else {
   367→    let n_float = as_float(2 * n)
   368→    let next_term = -term * x * x / ((n_float) * (n_float - 1.0))
   369→    cos_taylor(sum + next_term, next_term, n + 1, limit, x)
   370→  }
   371→}
   372→
   373→function asin_approx(x: Float) -> Float = {
   374→  // Simplified approximation
   375→  0.0
   376→}
   377→
   378→function atan_approx(x: Float) -> Float = {
   379→  // Simplified approximation
