   383→function fold[T, U](items: [T], init: U, f: fn(U, T) -> U) -> U = {
   384→  match items {
   385→    [] -> init,
   386→    _ -> fold(tail(items), f(init, items[0]), f)
   387→  }
   388→}
   389→
   390→function fold_zip(a: [Int], b: [Int], init: Int, f: fn(Int, Int, Int) -> Int) -> Int = {
   391→  if len(a) == 0 || len(b) == 0 {
   392→    init
   393→  } else {
   394→    fold_zip(tail(a), tail(b), f(init, a[0], b[0]), f)
   395→  }
   396→}
   397→
   398→function fold_index(start: Int, end: Int, init: Int, f: fn(Int, Int) -> Int) -> Int = {
   399→  if start >= end {
   400→    init
   401→  } else {
   402→    fold_index(start + 1, end, f(init, start), f)
   403→  }
   404→}
   405→
   406→function tail[T](arr: [T]) -> [T] = {
   407→  if len(arr) <= 1 {
   408→    []
   409→  } else {
   410→    []  // Simplified
   411→  }
   412→}
   413→
   414→function len[T](arr: [T]) -> Int = {
   415→  0  // Simplified
   416→}
