     6→module dispatch
     7→
     8→import types_extended
     9→
    10→// ============================================================================
    11→// 1. METHOD SIGNATURE & REGISTRY
    12→// ============================================================================
    13→
    14→// Method signature: function name + parameter types
    15→record MethodSignature {
    16→  name: String,
    17→  param_types: [String],
    18→  return_type: String
    19→}
    20→
    21→// Method entry: signature + implementation
    22→record MethodEntry {
    23→  signature: MethodSignature,
    24→  function_id: String,
    25→  specificity: Int  // 더 구체적인 타입일수록 높음
    26→}
    27→
    28→// Method Registry: 메서드 저장소
    29→record MethodRegistry {
    30→  methods: [MethodEntry],
    31→  lookup_cache: Map[String, [MethodEntry]]  // name -> entries
    32→}
    33→
    34→// ============================================================================
    35→// 2. TYPE MATCHING ALGORITHM
    36→// ============================================================================
    37→
    38→// Type rank: 타입의 우선순위 (더 구체적 = 높음)
    39→function type_rank(t: String) -> Int = match t {
    40→  "Int" -> 100,
    41→  "Float" -> 90,
    42→  "String" -> 95,
    43→  "Bool" -> 85,
    44→  "Dynamic" -> 1,  // 가장 추상적
    45→  _ -> 50  // 기타
    46→}
    47→
    48→// Type compatibility check
    49→function is_compatible(param_type: String, arg_type: String) -> Bool = {
    50→  if param_type == arg_type {
    51→    true
    52→  } else if param_type == "Dynamic" {
    53→    // Dynamic은 모든 타입과 호환
    54→    true
    55→  } else if arg_type == "Dynamic" {
    56→    // Dynamic 인자는 구체적 파라미터와 호환하지만 최저 우선순위
    57→    true
    58→  } else {
    59→    // 숫자 타입 간 호환성
    60→    (param_type == "Float" && arg_type == "Int") ||
    61→    (param_type == "Int" && arg_type == "Float")
    62→  }
    63→}
    64→
    65→// Calculate specificity score for method
    66→function calc_specificity(param_types: [String]) -> Int = {
    67→  fold(param_types, 0, fn(acc, t) -> acc + type_rank(t))
    68→}
    69→
    70→// ============================================================================
    71→// 3. METHOD LOOKUP & DISPATCH RESOLUTION
    72→// ============================================================================
    73→
    74→// Find best matching method
    75→function find_best_method(
    76→  registry: MethodRegistry,
    77→  name: String,
    78→  arg_types: [String]
    79→) -> Option[MethodEntry] = {
    80→  // Get candidates by name
    81→  let candidates = match registry.lookup_cache.get(name) {
    82→    Some(entries) -> entries,
    83→    None -> []
    84→  }
    85→
    86→  // Filter by arity (argument count)
    87→  let arity_match = filter(candidates, fn(entry) -> {
    88→    len(entry.signature.param_types) == len(arg_types)
    89→  })
    90→
    91→  // Filter by type compatibility
    92→  let type_match = filter(arity_match, fn(entry) -> {
    93→    fold(zip(entry.signature.param_types, arg_types), true, fn(acc, pair) -> {
    94→      acc && is_compatible(pair.0, pair.1)
    95→    })
    96→  })
    97→
    98→  // Sort by specificity (highest first)
    99→  let sorted = sort_by(type_match, fn(e) -> e.specificity)
   100→
   101→  // Return most specific method
   102→  if len(sorted) > 0 {
   103→    Some(sorted[0])
   104→  } else {
   105→    None
   106→  }
   107→}
   108→
   109→// Register new method
   110→function register_method(
   111→  registry: mutable MethodRegistry,
   112→  signature: MethodSignature,
   113→  function_id: String
   114→) -> Unit = {
   115→  let specificity = calc_specificity(signature.param_types)
   116→  let entry = MethodEntry {
   117→    signature: signature,
   118→    function_id: function_id,
   119→    specificity: specificity
   120→  }
   121→
   122→  // Add to methods list
   123→  registry.methods = append(registry.methods, entry)
   124→
   125→  // Update lookup cache
   126→  let name = signature.name
   127→  let existing = match registry.lookup_cache.get(name) {
   128→    Some(entries) -> entries,
   129→    None -> []
   130→  }
   131→  registry.lookup_cache.set(name, append(existing, entry))
   132→}
   133→
   134→// ============================================================================
   135→// 4. DISPATCH ENGINE
   136→// ============================================================================
   137→
   138→// Dispatch context: 디스패치 정보
   139→record DispatchContext {
   140→  method_name: String,
   141→  arg_types: [String],
   142→  registry: MethodRegistry
   143→}
   144→
   145→// Dispatch result
   146→type DispatchResult =
   147→  | Success(MethodEntry)
   148→  | NoMethodError(String)
   149→  | AmbiguousError([MethodEntry])
   150→
   151→// Perform method dispatch
   152→function dispatch(ctx: DispatchContext) -> DispatchResult = {
   153→  match find_best_method(ctx.registry, ctx.method_name, ctx.arg_types) {
   154→    Some(method) -> Success(method),
   155→    None -> NoMethodError(format(
   156→      "No method found for {}/{}",
   157→      ctx.method_name,
   158→      len(ctx.arg_types)
   159→    ))
   160→  }
   161→}
   162→
   163→// ============================================================================
   164→// 5. BUILT-IN METHOD REGISTRY
   165→// ============================================================================
   166→
   167→// Initialize registry with built-in methods
   168→function create_default_registry() -> MethodRegistry = {
   169→  let registry = MethodRegistry {
   170→    methods: [],
   171→    lookup_cache: Map::new[String, [MethodEntry]]()
   172→  }
   173→
   174→  // Register basic arithmetic operations
   175→  register_method(registry,
   176→    MethodSignature { name: "+", param_types: ["Int", "Int"], return_type: "Int" },
   177→    "builtin_add_int"
   178→  )
   179→
   180→  register_method(registry,
   181→    MethodSignature { name: "+", param_types: ["Float", "Float"], return_type: "Float" },
   182→    "builtin_add_float"
   183→  )
   184→
