## Phase 2: 자동미분 (`autograd.fl`)

### 설계 원칙

LLM 학습의 핵심인 역전파를 구현합니다. FreeLang의 `record` 와 `type` union을 활용한 **계산 그래프(Computation Graph)** 방식을 선택합니다.

### 핵심 레코드

```fl
// autograd.fl
module autograd

import tensor

// 그래프 노드 - 각 연산의 결과
record Variable {
  data: Tensor,           // forward 값
  grad: Tensor,           // backward gradient (동일 shape)
  requires_grad: Bool,    // gradient 추적 여부
  node_id: Int,           // 그래프에서 고유 ID
}

// 연산 타입 - backward 시 어떤 그래디언트를 계산할지
type OpType =
  | LeafOp                           // 파라미터 (leaf node)
  | AddOp(Variable, Variable)        // a + b
  | MulOp(Variable, Variable)        // a * b (element-wise)
  | MatmulOp(Variable, Variable)     // matmul
  | ReLUOp(Variable)                 // max(0, x)
  | SoftmaxOp(Variable)              // softmax
  | MeanOp(Variable)                 // mean reduction

// 계산 그래프의 엣지
record ComputeNode {
  output: Variable,
  op: OpType,
  inputs: Array[Variable],
}
```

### 핵심 함수 설계

**Forward 연산 (그래프 구축):**

```fl
// Variable 생성 (leaf node - 파라미터)
function var_from_tensor(t: Tensor, requires_grad: Bool, id: Int) -> Variable = {
  Variable {
    data: t,
    grad: zeros_tensor(t.shape),   // gradient는 0으로 초기화
    requires_grad: requires_grad,
    node_id: id
  }
}

// 덧셈 forward: z = a + b, 그래디언트는 각각 1
function var_add(a: Variable, b: Variable) -> ComputeNode = {
  let out_data = tensor_add(a.data, b.data)
  let out_var = var_from_tensor(out_data, a.requires_grad || b.requires_grad, next_id())
  ComputeNode {
    output: out_var,
    op: AddOp(a, b),
    inputs: array[Variable]([a, b])
  }
}

// matmul forward
function var_matmul(a: Variable, b: Variable) -> ComputeNode = {
  let out_data = matmul(a.data, b.data)
  let out_var = var_from_tensor(out_data, true, next_id())
  ComputeNode {
    output: out_var,
    op: MatmulOp(a, b),
    inputs: array[Variable]([a, b])
  }
}
```

**Backward 함수 (역전파 규칙):**

```fl
// 하나의 ComputeNode에 대해 gradient 전파
function backward_node(node: ComputeNode, output_grad: Tensor) -> Unit = {
  match node.op {
    LeafOp -> {
      // leaf: gradient 누적
      node.output.grad = tensor_add(node.output.grad, output_grad)
    },
    AddOp(a, b) -> {
      // d(a+b)/da = 1, d(a+b)/db = 1
      if a.requires_grad {
        a.grad = tensor_add(a.grad, output_grad)
      }
      if b.requires_grad {
        b.grad = tensor_add(b.grad, output_grad)
      }
    },
    MulOp(a, b) -> {
      // d(a*b)/da = b, d(a*b)/db = a
      if a.requires_grad {
        a.grad = tensor_add(a.grad, tensor_mul(output_grad, b.data))
      }
      if b.requires_grad {
        b.grad = tensor_add(b.grad, tensor_mul(output_grad, a.data))
      }
    },
    MatmulOp(a, b) -> {
      // dL/dA = dL/dC @ B^T,  dL/dB = A^T @ dL/dC
      if a.requires_grad {
        a.grad = tensor_add(a.grad, matmul(output_grad, transpose(b.data)))
      }
      if b.requires_grad {
        b.grad = tensor_add(b.grad, matmul(transpose(a.data), output_grad))
      }
    },
    ReLUOp(x) -> {
      // d(relu(x))/dx = 1 if x > 0, else 0
      let mask = map_float(x.data, fn(v) -> if v > 0.0 { 1.0 } else { 0.0 })
      x.grad = tensor_add(x.grad, tensor_mul_data(output_grad, mask))
    },
  }
}

// 전체 그래프에 대해 backward (위상정렬 순서)
// graph: Array[ComputeNode] (역순으로 저장됨)
function backward(graph: Array[ComputeNode], loss_var: Variable) -> Unit = {
  // loss의 gradient = 1
  let loss_grad = ones_tensor(loss_var.data.shape)
  loss_var.grad = loss_grad
  // 역방향으로 각 노드 backward
  let rev_graph = reverse(graph)
  fold(rev_graph, Unit, fn(_, node) -> {
    backward_node(node, node.output.grad)
  })
}
```

### Phase 2 테스트 케이스 아이디어

- `var_add` 후 backward → 양쪽 grad == output_grad 확인
- `var_matmul` 후 backward → 수치 미분(numerical gradient)과 비교 검증
- ReLU backward: 음수 입력에서 grad = 0 확인
- 연쇄 규칙: `c = relu(a @ b + bias)` 의 grad 체인

