## Phase 3: 신경망 레이어 (`nn.fl`)

### 설계 원칙

레이어를 `record` 로 정의하고, `forward(layer, input)` 함수를 멀티플 디스패치로 오버로딩합니다. 이것이 FreeLang의 Julia 스타일 다중 디스패치 철학과 일치합니다.

### 핵심 레코드

```fl
// nn.fl
module nn

import autograd
import math

// Linear 레이어: y = xW^T + b
record Linear {
  weight: Variable,    // shape: [out_features, in_features]
  bias: Variable,      // shape: [out_features]
  in_features: Int,
  out_features: Int,
}

// LayerNorm: 각 토큰을 정규화
record LayerNorm {
  weight: Variable,    // gamma, shape: [normalized_shape]
  bias: Variable,      // beta,  shape: [normalized_shape]
  normalized_shape: Int,
  eps: Float,
}

// Dropout (추론 시 비활성화)
record Dropout {
  p: Float,            // drop probability
  training: Bool,
}
```

### Linear 레이어

```fl
// Xavier/Glorot 초기화
function linear(in_features: Int, out_features: Int, seed: Int) -> Linear = {
  // Xavier: std = sqrt(2 / (fan_in + fan_out))
  let std = sqrt(2.0 / as_float(in_features + out_features))
  let w_data = tensor_scale(randn_tensor(array[Int]([out_features, in_features]), seed), std)
  let b_data = zeros_tensor(array[Int]([out_features]))
  Linear {
    weight: var_from_tensor(w_data, true, new_id()),
    bias: var_from_tensor(b_data, true, new_id()),
    in_features: in_features,
    out_features: out_features
  }
}

// forward: input shape [batch, in], output shape [batch, out]
function forward_linear(layer: Linear, x: Variable) -> ComputeNode = {
  // y = x @ W^T + b
  let wt = transpose_var(layer.weight)
  let xw_node = var_matmul(x, wt)
  let out_node = var_add(xw_node.output, broadcast_bias(layer.bias, x.data.shape))
  out_node
}
```

### Activation 함수들

```fl
// ReLU: max(0, x)
function relu(x: Variable) -> ComputeNode = {
  let out_data = map_float(x.data, fn(v) -> if v > 0.0 { v } else { 0.0 })
  let out_var = var_from_tensor(out_data, x.requires_grad, new_id())
  ComputeNode {
    output: out_var,
    op: ReLUOp(x),
    inputs: array[Variable]([x])
  }
}

// GELU: x * Phi(x)  [GPT-2 사용]
// 근사: 0.5 * x * (1 + tanh(sqrt(2/pi) * (x + 0.044715 * x^3)))
function gelu(x: Variable) -> ComputeNode = {
  let SQRT_2_PI = 0.7978845608
  let COEF = 0.044715
  let out_data = map_float(x.data, fn(v) -> {
    let inner = SQRT_2_PI * (v + COEF * v * v * v)
    0.5 * v * (1.0 + tanh(inner))
  })
  let out_var = var_from_tensor(out_data, x.requires_grad, new_id())
  ComputeNode {
    output: out_var,
    op: GELUOp(x),
    inputs: array[Variable]([x])
  }
}

// Softmax: exp(xi) / sum(exp(xj))
// numerically stable: subtract max first
function softmax(x: Variable) -> ComputeNode = {
  let out_data = softmax_stable(x.data)
  let out_var = var_from_tensor(out_data, x.requires_grad, new_id())
  ComputeNode {
    output: out_var,
    op: SoftmaxOp(x),
    inputs: array[Variable]([x])
  }
}

function softmax_stable(t: Tensor) -> Tensor = {
  let max_val = max_float_arr(t.data)
  let shifted = map_float(t.data, fn(v) -> exp(v - max_val))
  let sum = sum_float_arr(shifted)
  map_float(shifted, fn(v) -> v / sum)
}
```

### LayerNorm

```fl
// LayerNorm: (x - mean) / std * gamma + beta
function layer_norm(x: Variable, ln: LayerNorm) -> ComputeNode = {
  let eps = ln.eps
  let mean = mean_float_tensor(x.data)
  let centered = map_float(x.data, fn(v) -> v - mean)
  let var_val = mean_float_arr(map_float(centered, fn(v) -> v * v))
  let std = sqrt(var_val + eps)
  let normalized = map_float(centered, fn(v) -> v / std)
  // scale and shift: gamma * normalized + beta
  let scaled = tensor_mul(normalized_var, ln.weight)
  let shifted = tensor_add(scaled.output, ln.bias)
  shifted
}
```

### Phase 3 테스트 케이스 아이디어

- `linear(4, 2)` forward: output shape 확인 `[batch, 2]`
- `relu([-1, 0, 1])` → `[0, 0, 1]` 정확성
- `softmax([1, 2, 3])` 합이 1.0에 근접
- `layer_norm` 출력의 mean ≈ 0, std ≈ 1 확인

