## Phase 4: Attention 메커니즘 (`attention.fl`)

### 설계 원칙

Scaled Dot-Product Attention이 LLM의 핵심입니다. `sqrt(d_k)` 스케일링과 인과적 마스크(causal mask)가 필수 구현 요소입니다.

### 핵심 레코드

```fl
// attention.fl
module attention

import nn
import autograd

// 단일 헤드 Attention 설정
record AttentionConfig {
  d_model: Int,      // 모델 차원 (예: 512)
  d_k: Int,          // key/query 차원
  d_v: Int,          // value 차원
  seq_len: Int,      // 최대 시퀀스 길이
  use_causal_mask: Bool,  // GPT는 true
}

// Multi-Head Attention 레이어
record MultiHeadAttention {
  num_heads: Int,
  d_model: Int,
  d_head: Int,       // d_model / num_heads
  w_q: Linear,       // Query 투영
  w_k: Linear,       // Key 투영
  w_v: Linear,       // Value 투영
  w_o: Linear,       // Output 투영
  use_causal_mask: Bool,
}
```

### Scaled Dot-Product Attention

```fl
// Attention(Q, K, V) = softmax(QK^T / sqrt(d_k)) * V
// Q: [seq, d_k], K: [seq, d_k], V: [seq, d_v]
function scaled_dot_product_attention(
  q: Variable,
  k: Variable,
  v: Variable,
  d_k: Int,
  causal_mask: Option[Tensor]
) -> ComputeNode = {
  // Step 1: QK^T 계산 -> [seq, seq]
  let scores_node = var_matmul(q, transpose_var(k))

  // Step 2: 1/sqrt(d_k) 스케일링
  let scale = 1.0 / sqrt(as_float(d_k))
  let scaled_node = var_scale(scores_node.output, scale)

  // Step 3: causal mask 적용 (GPT: 미래 토큰 차단)
  let masked_node = match causal_mask {
    Some(mask) -> var_add_mask(scaled_node.output, mask),
    None -> scaled_node
  }

  // Step 4: Softmax
  let attn_node = softmax(masked_node.output)

  // Step 5: V와 곱
  let out_node = var_matmul(attn_node.output, v)
  out_node
}

// Causal mask 생성: 상삼각 행렬을 -inf로
function make_causal_mask(seq_len: Int) -> Tensor = {
  let mask = zeros_tensor(array[Int]([seq_len, seq_len]))
  fold_range(0, seq_len, mask, fn(m, i) -> {
    fold_range(i + 1, seq_len, m, fn(m2, j) -> {
      tensor_set(m2, array[Int]([i, j]), -100000.0)  // -inf 근사
    })
  })
}
```

### Multi-Head Attention

```fl
// Multi-Head Attention 생성
function multi_head_attention(
  d_model: Int,
  num_heads: Int,
  seed: Int
) -> MultiHeadAttention = {
  let d_head = d_model / num_heads
  MultiHeadAttention {
    num_heads: num_heads,
    d_model: d_model,
    d_head: d_head,
    w_q: linear(d_model, d_model, seed),
    w_k: linear(d_model, d_model, seed + 1),
    w_v: linear(d_model, d_model, seed + 2),
    w_o: linear(d_model, d_model, seed + 3),
    use_causal_mask: true
  }
}

// forward: x [batch, seq, d_model] -> [batch, seq, d_model]
function forward_mha(mha: MultiHeadAttention, x: Variable) -> ComputeNode = {
  let seq_len = x.data.shape.data[1]
  let causal_mask = if mha.use_causal_mask {
    Some(make_causal_mask(seq_len))
  } else {
    None
  }

  // Q, K, V 투영
  let q_node = forward_linear(mha.w_q, x)
  let k_node = forward_linear(mha.w_k, x)
  let v_node = forward_linear(mha.w_v, x)

  // 헤드 분리: [batch, seq, d_model] -> [batch, num_heads, seq, d_head]
  // (단순화: 단일 배치, reshape + transpose)
  let q_split = split_heads(q_node.output, mha.num_heads, mha.d_head)
  let k_split = split_heads(k_node.output, mha.num_heads, mha.d_head)
  let v_split = split_heads(v_node.output, mha.num_heads, mha.d_head)

  // Attention 계산 (각 헤드 독립적)
  let attn_out = scaled_dot_product_attention(
    q_split, k_split, v_split,
    mha.d_head, causal_mask
  )

  // 헤드 합치기 + 출력 투영
  let merged = merge_heads(attn_out.output, mha.num_heads, mha.d_head)
  let out_node = forward_linear(mha.w_o, merged)
  out_node
}
```

