## Phase 5: Transformer 블록 (`transformer.fl`)

### TransformerBlock 설계

GPT-2 스타일의 Pre-LayerNorm 구조를 채택합니다 (Post-LN보다 학습 안정성이 높음).

```fl
// transformer.fl
module transformer

import attention
import nn

// FFN: Feed-Forward Network
record FFN {
  fc1: Linear,    // d_model -> 4 * d_model (확장)
  fc2: Linear,    // 4 * d_model -> d_model (압축)
}

// Transformer 블록: Pre-LN 구조
// x -> LN -> MHA -> + -> LN -> FFN -> +
record TransformerBlock {
  mha: MultiHeadAttention,
  ffn: FFN,
  ln1: LayerNorm,
  ln2: LayerNorm,
  d_model: Int,
}

// GPT 모델 전체
record GPTModel {
  token_embedding: Tensor,   // [vocab_size, d_model]
  pos_embedding: Tensor,     // [max_seq_len, d_model]
  blocks: Array[TransformerBlock],
  ln_final: LayerNorm,
  lm_head: Linear,           // [d_model, vocab_size]
  config: GPTConfig,
}

record GPTConfig {
  vocab_size: Int,
  d_model: Int,
  num_heads: Int,
  num_layers: Int,
  max_seq_len: Int,
  ffn_dim: Int,     // 보통 4 * d_model
}
```

### 블록 Forward

```fl
// TransformerBlock forward (Pre-LN)
function forward_block(block: TransformerBlock, x: Variable) -> ComputeNode = {
  // Sub-layer 1: MHA with residual
  let ln1_out = layer_norm(x, block.ln1)
  let mha_out = forward_mha(block.mha, ln1_out.output)
  let res1 = var_add(x, mha_out.output)   // residual connection

  // Sub-layer 2: FFN with residual
  let ln2_out = layer_norm(res1.output, block.ln2)
  let ffn_out = forward_ffn(block.ffn, ln2_out.output)
  let res2 = var_add(res1.output, ffn_out.output)

  res2
}

// FFN forward: GELU 활성화
function forward_ffn(ffn: FFN, x: Variable) -> ComputeNode = {
  let h = forward_linear(ffn.fc1, x)
  let h_act = gelu(h.output)              // GELU 활성화
  let out = forward_linear(ffn.fc2, h_act.output)
  out
}

// GPT forward: 토큰 시퀀스 -> 로짓
function forward_gpt(model: GPTModel, token_ids: Array[Int]) -> Tensor = {
  let seq_len = token_ids.size

  // 임베딩: 토큰 + 위치
  let tok_emb = gather_rows(model.token_embedding, token_ids)
  let pos_emb = slice_rows(model.pos_embedding, 0, seq_len)
  let x = var_from_tensor(tensor_add(tok_emb, pos_emb), false, 0)

  // 각 블록 통과
  let final_x = fold(model.blocks, x, fn(h, block) -> {
    let out = forward_block(block, h)
    out.output
  })

  // Final LayerNorm + LM head
  let ln_out = layer_norm(final_x, model.ln_final)
  let logits_node = forward_linear(model.lm_head, ln_out.output)
  logits_node.output.data
}
```

