## Phase 1: 텐서 연산 기반 (`tensor.fl`)

### 설계 원칙

기존 `arrays.fl`의 `Array[T]` 패턴을 확장합니다. 핵심 차이점은 `strides` 필드를 추가해 reshape/transpose가 데이터 복사 없이 뷰(view)로 작동하도록 설계하는 것입니다.

### 핵심 레코드

```fl
// tensor.fl
module tensor

import math
import arrays

// 텐서 핵심 타입: 1D 평탄화 데이터 + shape + strides
record Tensor {
  data: Array[Float],    // 실제 데이터 (항상 1D 평탄화)
  shape: Array[Int],     // 예: [3, 4] = 3행 4열
  strides: Array[Int],   // 예: [4, 1] = 행 stride, 열 stride
  ndim: Int,             // 차원 수
  size: Int,             // 전체 원소 수
}
```

### 핵심 함수 설계

**텐서 생성 함수들:**

```fl
// 0으로 초기화된 텐서
function zeros_tensor(shape: Array[Int]) -> Tensor = {
  let size = product_int(shape)
  let data = fill_float(size, 0.0)
  let strides = compute_strides(shape)
  Tensor {
    data: data,
    shape: shape,
    strides: strides,
    ndim: shape.size,
    size: size
  }
}

// 1으로 초기화
function ones_tensor(shape: Array[Int]) -> Tensor = {
  let size = product_int(shape)
  let data = fill_float(size, 1.0)
  Tensor {
    data: data,
    shape: shape,
    strides: compute_strides(shape),
    ndim: shape.size,
    size: size
  }
}

// 정규분포 랜덤 초기화 (Xavier 초기화에 사용)
// 단순 선형합동 생성기(LCG) 기반 pseudo-random
function randn_tensor(shape: Array[Int], seed: Int) -> Tensor = {
  let size = product_int(shape)
  let data = randn_array(size, seed)   // Box-Muller 변환
  Tensor {
    data: data,
    shape: shape,
    strides: compute_strides(shape),
    ndim: shape.size,
    size: size
  }
}
```

**인덱싱 (다차원 → 1D 매핑):**

```fl
// [i, j, k] → 1D offset (strides 이용)
function flat_index(tensor: Tensor, indices: Array[Int]) -> Int = {
  fold_range(0, tensor.ndim, 0, fn(acc, dim) -> {
    acc + tensor.strides.data[dim] * indices.data[dim]
  })
}

function tensor_get(t: Tensor, indices: Array[Int]) -> Float = {
  let idx = flat_index(t, indices)
  t.data.data[idx]
}
```

**행렬 곱 (matmul) - LLM의 핵심 연산:**

```fl
// 2D matmul: (M, K) @ (K, N) -> (M, N)
// 이것이 Linear 레이어와 Attention의 기반
function matmul(a: Tensor, b: Tensor) -> Tensor = {
  let m = a.shape.data[0]
  let k = a.shape.data[1]
  let n = b.shape.data[1]
  let result = zeros_tensor(array[Int]([m, n]))
  fold_range(0, m, result, fn(r, i) -> {
    fold_range(0, n, r, fn(r2, j) -> {
      let sum = fold_range(0, k, 0.0, fn(acc, p) -> {
        let av = tensor_get(a, array[Int]([i, p]))
        let bv = tensor_get(b, array[Int]([p, j]))
        acc + av * bv
      })
      tensor_set(r2, array[Int]([i, j]), sum)
    })
  })
}
```

**원소별 연산 (element-wise):**

```fl
// 두 텐서의 원소별 덧셈 (broadcasting은 1D로 단순화)
function tensor_add(a: Tensor, b: Tensor) -> Tensor = {
  let new_data = map_indexed_float(a.data, fn(i, v) -> v + b.data.data[i])
  Tensor { data: new_data, shape: a.shape, strides: a.strides,
           ndim: a.ndim, size: a.size }
}

// 스칼라 곱
function tensor_scale(t: Tensor, scalar: Float) -> Tensor = {
  let new_data = map_float(t.data, fn(v) -> v * scalar)
  Tensor { data: new_data, shape: t.shape, strides: t.strides,
           ndim: t.ndim, size: t.size }
}
```

**reshape & transpose:**

```fl
// reshape: 데이터 복사 없이 shape/strides 교체
function reshape(t: Tensor, new_shape: Array[Int]) -> Tensor = {
  Tensor {
    data: t.data,                      // 동일한 데이터 공유
    shape: new_shape,
    strides: compute_strides(new_shape),
    ndim: new_shape.size,
    size: t.size
  }
}

// transpose: 2D 행렬 전치 (shape, strides 교체)
function transpose(t: Tensor) -> Tensor = {
  // [m, n] -> [n, m], strides 반전
  let new_shape = array[Int]([t.shape.data[1], t.shape.data[0]])
  let new_strides = array[Int]([t.strides.data[1], t.strides.data[0]])
  Tensor {
    data: t.data,
    shape: new_shape,
    strides: new_strides,
    ndim: t.ndim,
    size: t.size
  }
}
```

### Phase 1 헬퍼 함수

```fl
// strides 계산 (C-contiguous, row-major)
// shape [3, 4, 5] -> strides [20, 5, 1]
function compute_strides(shape: Array[Int]) -> Array[Int] = {
  let ndim = shape.size
  let strides = ones_int(ndim)       // [1, 1, ..., 1]
  fold_range_rev(0, ndim - 1, strides, fn(s, i) -> {
    let stride_val = s.data[i + 1] * shape.data[i + 1]
    set_int(s, i, stride_val)
  })
}

// 정수 배열의 곱
function product_int(arr: Array[Int]) -> Int = {
  fold(arr, 1, fn(acc, x) -> acc * x)
}

// Box-Muller 변환으로 정규분포 근사
function randn_array(size: Int, seed: Int) -> Array[Float] = {
  fold_range(0, size, array[Float]([]), fn(acc, i) -> {
    let u1 = lcg_float(seed + i * 2)
    let u2 = lcg_float(seed + i * 2 + 1)
    // z = sqrt(-2*ln(u1)) * cos(2*pi*u2)
    let z = sqrt(-2.0 * log(u1 + 0.0001)) * cos(2.0 * PI * u2)
    append_float(acc, z)
  })
}
```

### Phase 1 테스트 케이스 (20개)

| # | 테스트 | 검증 포인트 |
|---|--------|------------|
| 1 | `zeros_tensor([3,4]).size == 12` | 기본 생성 |
| 2 | `ones_tensor([2,2]).data[0] == 1.0` | 초기화 값 |
| 3 | `flat_index([0,1], strides=[4,1]) == 1` | 인덱스 계산 |
| 4 | `reshape([6], [2,3]).ndim == 2` | reshape |
| 5 | `transpose([2,3]).shape == [3,2]` | transpose shape |
| 6 | `matmul(I2, A) == A` (단위행렬) | matmul 정확성 |
| 7 | `tensor_add(A, B).data[0]` | 원소별 덧셈 |
| 8 | `tensor_scale(A, 2.0)` | 스칼라 곱 |
| 9 | `slice_tensor([0:2, :])` | 슬라이스 |
| 10 | `randn_tensor([100]).mean ≈ 0.0` | 랜덤 초기화 |

