## Phase 6: 학습 루프 (`trainer.fl`)

### 설계 원칙

실용적인 Adam 옵티마이저와 CrossEntropy 손실 함수를 구현합니다. 파라미터 수집은 FreeLang의 `fold` 를 이용합니다.

### 핵심 레코드

```fl
// trainer.fl
module trainer

import transformer

// Adam 옵티마이저 상태
record AdamState {
  lr: Float,           // 학습률 (예: 3e-4)
  beta1: Float,        // 1차 모멘트 (0.9)
  beta2: Float,        // 2차 모멘트 (0.999)
  eps: Float,          // 수치 안정성 (1e-8)
  t: Int,              // 스텝 수 (편향 보정에 사용)
  m: Array[Tensor],    // 1차 모멘트 (각 파라미터별)
  v: Array[Tensor],    // 2차 모멘트 (각 파라미터별)
}

// 학습 설정
record TrainConfig {
  batch_size: Int,
  seq_len: Int,
  num_epochs: Int,
  log_interval: Int,   // 몇 스텝마다 loss 출력
}

// 미니배치
record Batch {
  input_ids: Array[Array[Int]],   // [batch, seq]
  target_ids: Array[Array[Int]],  // [batch, seq] (input을 1 shift)
}
```

### 손실 함수

```fl
// Cross-Entropy Loss: -sum(target * log(softmax(logits)))
function cross_entropy(logits: Variable, targets: Array[Int]) -> ComputeNode = {
  let probs_node = softmax(logits)
  // NLL: -log(prob[target_class])
  let loss_data = fold_range(0, targets.size, 0.0, fn(acc, i) -> {
    let target_class = targets.data[i]
    let prob = tensor_get(probs_node.output.data, array[Int]([i, target_class]))
    acc + (-log(prob + 1e-9))
  })
  let mean_loss = loss_data / as_float(targets.size)
  let loss_tensor = scalar_tensor(mean_loss)
  let loss_var = var_from_tensor(loss_tensor, true, new_id())
  ComputeNode {
    output: loss_var,
    op: CrossEntropyOp(logits, targets),
    inputs: array[Variable]([logits])
  }
}

// MSE Loss
function mse_loss(pred: Variable, target: Tensor) -> ComputeNode = {
  let diff = tensor_sub(pred.data, target)
  let sq = map_float(diff, fn(v) -> v * v)
  let mean_val = mean_float_arr(sq)
  let loss_tensor = scalar_tensor(mean_val)
  let loss_var = var_from_tensor(loss_tensor, true, new_id())
  ComputeNode {
    output: loss_var,
    op: MSEOp(pred, target),
    inputs: array[Variable]([pred])
  }
}
```

### Adam 옵티마이저

```fl
// Adam 초기화
function adam(params: Array[Variable], lr: Float) -> AdamState = {
  let zero_moments = map(params, fn(p) -> zeros_tensor(p.data.shape))
  AdamState {
    lr: lr,
    beta1: 0.9,
    beta2: 0.999,
    eps: 1e-8,
    t: 0,
    m: zero_moments,
    v: zero_moments
  }
}

// Adam 한 스텝 업데이트
function adam_step(
  state: mutable AdamState,
  params: Array[Variable]
) -> Unit = {
  state.t = state.t + 1
  let t_float = as_float(state.t)
  let bc1 = 1.0 - pow_float(state.beta1, state.t)  // 편향 보정
  let bc2 = 1.0 - pow_float(state.beta2, state.t)

  fold_range(0, params.size, Unit, fn(_, i) -> {
    let param = params.data[i]
    let grad = param.grad
    // m = beta1 * m + (1-beta1) * grad
    let new_m = tensor_add(
      tensor_scale(state.m.data[i], state.beta1),
      tensor_scale(grad, 1.0 - state.beta1)
    )
    // v = beta2 * v + (1-beta2) * grad^2
    let new_v = tensor_add(
      tensor_scale(state.v.data[i], state.beta2),
      tensor_scale(tensor_mul(grad, grad), 1.0 - state.beta2)
    )
    state.m.data[i] = new_m
    state.v.data[i] = new_v
    // 보정된 추정치
    let m_hat = tensor_scale(new_m, 1.0 / bc1)
    let v_hat = tensor_scale(new_v, 1.0 / bc2)
    // 파라미터 업데이트: p -= lr * m_hat / (sqrt(v_hat) + eps)
    let denom = map_float(v_hat, fn(v) -> sqrt(v) + state.eps)
    let update = tensor_div(m_hat, denom)
    param.data = tensor_sub(param.data, tensor_scale(update, state.lr))
    // gradient 초기화
    param.grad = zeros_tensor(param.data.shape)
  })
}
```

### 학습 루프

```fl
// 전체 학습 루프
function train(
  model: mutable GPTModel,
  data: Array[Batch],
  config: TrainConfig
) -> Unit = {
  let params = collect_params(model)
  let optim = adam(params, 0.0003)
  let graph = empty_graph()

  fold_range(0, config.num_epochs, Unit, fn(_, epoch) -> {
    fold(data, Unit, fn(_, batch) -> {
      // Forward pass
      let logits = forward_gpt(model, flatten_batch(batch.input_ids))
      let loss_node = cross_entropy(
        var_from_tensor(logits, true, new_id()),
        flatten_int(batch.target_ids)
      )

      // Backward pass
      backward(graph, loss_node.output)

      // 파라미터 업데이트
      adam_step(optim, params)

      // Logging
      if mod(optim.t, config.log_interval) == 0 {
        println(format("step {}: loss = {}", optim.t,
                       scalar_val(loss_node.output.data)))
      }
    })
  })
}

// GPT 모델에서 학습 가능한 파라미터 수집
function collect_params(model: GPTModel) -> Array[Variable] = {
  let params = array[Variable]([])
  // 임베딩
  let params = append_var(params, var_from_tensor(model.token_embedding, true, 0))
  let params = append_var(params, var_from_tensor(model.pos_embedding, true, 1))
  // 각 블록의 파라미터
  fold(model.blocks, params, fn(p, block) -> {
    let p = append_vars(p, block_params(block))
    p
  })
}
```

